INSERT INTO public.vocab_tower_words (grade, word, category, level, definition, example)
VALUES
    (3, '감각', '나와 몸', 2, '눈, 코, 입, 귀, 피부를 통해 주변의 자극을 느끼는 능력을 말해요.', '맛있는 떡볶이 냄새를 맡으니 후각 감각이 살아나는 기분이야.'),
    (3, '강력', '감정과 태도', 1, '힘이나 기운이 무척 세고 당당한 것을 말해요.', '우리 팀은 강력한 응원 덕분에 줄다리기에서 이길 수 있었어.'),
    (3, '견학', '학교생활', 1, '직접 현장에 가서 보고 배우는 즐거운 활동을 말해요.', '내일은 우리 반 모두가 과학관으로 견학을 가는 날이야.'),
    (3, '공경', '감정과 태도', 2, '어른이나 훌륭한 사람을 우러러보고 예의 바르게 모시는 마음이에요.', '명절에 할머니께 정성껏 절을 올리며 공경하는 마음을 전했어.'),
    (3, '과제', '학교생활', 1, '선생님이 내주신 숙제나 우리가 꼭 해결해야 할 문제를 말해요.', '오늘 과제는 우리 동네의 멋진 장소를 조사해 오는 거야.'),
    (3, '교문', '학교생활', 1, '학교의 입구에 있는 커다란 문을 말해요.', '아침마다 교문에서 웃으며 인사해 주시는 선생님을 만나면 기분이 좋아.'),
    (3, '구실', '감정과 태도', 3, '자기가 맡은 의무나 책임을 다하는 것을 말해요.', '모둠 활동에서 각자 자기 구실을 다해야 멋진 결과물이 나와.'),
    (3, '금지', '학교생활', 1, '어떤 일을 하지 못하게 막는 규칙을 말해요.', '복도에서는 안전을 위해 뛰는 것이 금지되어 있어.'),
    (3, '기본형', '말과 글', 3, '단어가 변하기 전의 가장 바탕이 되는 모습을 말해요.', '''먹고, 먹으니, 먹어서''의 기본형은 ''먹다''라고 해.'),
    (3, '기후', '자연과 환경', 2, '어떤 지역에서 오랫동안 나타나는 날씨의 평균적인 상태를 말해요.', '우리나라는 사계절이 뚜렷한 기후를 가지고 있어.'),
    (3, '낭송', '말과 글', 2, '시나 글을 목소리 높여 감정을 담아 읽는 것을 말해요.', '국어 시간에 내가 쓴 시를 친구들 앞에서 멋지게 낭송했어.'),
    (3, '능력', '나와 몸', 2, '어떤 일을 잘 해낼 수 있는 힘을 말해요.', '친구는 복잡한 퍼즐을 순식간에 맞추는 특별한 능력이 있어.'),
    (3, '대표', '학교생활', 1, '모임을 대신해서 나선 사람이나 물건을 말해요.', '우리 반 대표로 나간 친구가 달리기 시합에서 1등을 했어.'),
    (3, '대화', '사회와 소통', 1, '서로 마주 보고 이야기를 주고받는 것을 말해요.', '짝꿍과 대화를 나누다 보니 서로 좋아하는 게임이 같다는 걸 알게 됐어.'),
    (3, '도시', '사회와 소통', 1, '사람이 많이 살고 건물과 차가 많은 복잡한 곳을 말해요.', '밤이 되면 도시의 불빛들이 별처럼 반짝거려.'),
    (3, '문장', '말과 글', 1, '생각이나 감정을 완벽하게 나타내는 글의 마디를 말해요.', '일기장에 오늘 있었던 일을 정성껏 한 문장씩 써 내려갔어.'),
    (3, '분리', '자연과 환경', 2, '종류에 따라 나누어 따로 떼어놓는 것을 말해요.', '지구를 위해 플라스틱과 종이를 꼼꼼하게 분리해서 버렸어.'),
    (3, '사물', '자연과 환경', 2, '우리 주변에 있는 모든 물건이나 물체를 말해요.', '교실 안에 있는 사물들을 관찰하고 특징을 적어 보았어.'),
    (3, '사전', '생각과 공부', 1, '단어의 뜻을 풀이해 놓은 두꺼운 책이나 프로그램을 말해요.', '모르는 단어가 나오면 사전을 찾아서 정확한 뜻을 공부했어.'),
    (3, '생략', '말과 글', 3, '줄거리나 내용 중 일부를 줄이거나 빼는 것을 말해요.', '제목이 너무 길어서 앞부분을 생략하고 간단히 적었어.'),
    (3, '생신', '가족과 이웃', 1, '어른의 생일을 높여서 부르는 예쁜 말이에요.', '할아버지 생신을 맞아 온 가족이 모여 축하 노래를 불렀어.'),
    (3, '서약서', '학교생활', 3, '약속을 꼭 지키겠다고 다짐하며 적은 종이를 말해요.', '학기 초에 우리 반 규칙을 잘 지키겠다는 서약서를 썼어.'),
    (3, '성공', '감정과 태도', 1, '목표했던 일을 멋지게 이루어 내는 것을 말해요.', '어려운 수학 문제를 포기하지 않고 끝까지 풀어서 성공했어!'),
    (3, '소용', '감정과 태도', 2, '어디에 쓰임새가 있거나 도움이 되는 것을 말해요.', '비가 그친 뒤에는 우산이 아무 소용이 없게 됐어.'),
    (3, '속담', '말과 글', 2, '옛날부터 전해 내려오는 지혜가 담긴 짧은 말을 말해요.', '''가는 말이 고와야 오는 말이 곱다''라는 속담은 참 맞는 말이야.'),
    (3, '실천', '감정과 태도', 2, '생각한 것이나 계획한 일을 실제로 행동에 옮기는 거예요.', '일찍 일어나기로 한 계획을 오늘 아침에 바로 실천했어.'),
    (3, '안내문', '학교생활', 1, '여러 사람에게 소식을 알리기 위해 적은 글을 말해요.', '게시판에 붙은 급식 안내문을 보고 오늘 메뉴를 확인했어.'),
    (3, '안전', '학교생활', 1, '위험하지 않고 마음이 놓이는 편안한 상태를 말해요.', '자전거를 탈 때는 안전을 위해 꼭 헬멧을 써야 해.'),
    (3, '언어', '사회와 소통', 2, '생각이나 느낌을 전하기 위해 사용하는 말이나 글이에요.', '우리는 한국어라는 예쁜 언어를 사용하며 살고 있어.'),
    (3, '여유', '감정과 태도', 2, '서두르지 않고 마음이 넉넉하고 편안한 상태를 말해요.', '숙제를 미리 끝내 놓으니 마음속에 여유가 생겼어.'),
    (3, '역할', '사회와 소통', 2, '자기가 맡은 일이나 해야 할 직분을 말해요.', '연극놀이에서 나는 나무 역할을 맡아 멋지게 서 있었어.'),
    (3, '연구', '과학과 기술', 3, '어떤 사실을 깊이 있게 조사하고 공부하는 것을 말해요.', '과학자들은 병을 고치기 위해 매일 열심히 연구하고 계셔.'),
    (3, '외국', '사회와 소통', 1, '우리나라가 아닌 다른 나라를 말해요.', '외국에서 온 친구에게 우리 학교를 친절하게 소개해 주었어.'),
    (3, '외삼촌', '가족과 이웃', 1, '어머니의 남자 형제를 부르는 말이에요.', '방학 때 외삼촌 댁에 가서 사촌 동생들과 신나게 놀았어.'),
    (3, '원인', '생각과 공부', 2, '어떤 일이 일어나게 된 근본적인 이유를 말해요.', '배가 아픈 원인을 생각해보니 아까 찬 우유를 너무 많이 마셨어.'),
    (3, '일기', '말과 글', 1, '날마다 그날 있었던 일과 생각을 기록하는 글이에요.', '잠들기 전 책상에 앉아 오늘 하루 중 가장 기억에 남는 일을 일기에 썼어.'),
    (3, '일회용', '자연과 환경', 1, '한 번만 쓰고 버리도록 만들어진 물건을 말해요.', '지구가 아프지 않게 일회용 종이컵 대신 개인 텀블러를 사용하자.'),
    (3, '장소', '사회와 소통', 1, '어떤 일이 일어나거나 사람이 모이는 곳을 말해요.', '우리가 만나기로 한 장소는 학교 정문 앞이야.'),
    (3, '전통', '우리 역사', 2, '옛날부터 오늘날까지 전해 내려오는 우리 고유의 것을 말해요.', '한복은 우리나라의 아름다운 전통 의상이야.'),
    (3, '전학', '학교생활', 1, '다니던 학교를 옮겨서 다른 학교로 가는 것을 말해요.', '새로 전학 온 친구가 낯설지 않게 먼저 가서 인사해 주었어.'),
    (3, '전화', '과학과 기술', 1, '멀리 떨어져 있는 사람과 목소리로 소식을 주고받는 도구예요.', '엄마께 전화를 걸어 오늘 학교에서 있었던 즐거운 일을 말씀드렸어.'),
    (3, '정리', '학교생활', 1, '어지러운 상태를 질서 있게 바로잡는 것을 말해요.', '수업이 끝나고 내 책상 위를 깨끗하게 정리했어.'),
    (3, '정보', '과학과 기술', 2, '우리가 어떤 일을 결정하는 데 도움이 되는 소식이나 자료를 말해요.', '인터넷에서 이번 주말 날씨 정보를 찾아보고 나들이 계획을 세웠어.'),
    (3, '종일', '시간과 생활', 1, '아침부터 저녁까지 하루 전체를 말해요.', '주말 내내 비가 와서 집 안에서 종일 책만 읽었어.'),
    (3, '중요', '감정과 태도', 1, '가볍게 여길 수 없을 만큼 가치 있고 귀한 것을 말해요.', '친구와의 약속을 지키는 것은 세상에서 아주 중요한 일이야.'),
    (3, '지방', '사회와 소통', 2, '서울이 아닌 다른 지역이나 어느 한 구역을 말해요.', '여름방학 때 공기 맑은 지방에 계신 할머니 댁에 방문했어.'),
    (3, '참가', '학교생활', 1, '모임이나 단체 활동에 함께 참여하는 것을 말해요.', '이번 학교 글짓기 대회에 참가해서 내 솜씨를 뽐내고 싶어.'),
    (3, '채집', '과학과 기술', 2, '연구를 위해 식물이나 곤충 등을 찾아 모으는 활동을 말해요.', '숲체험 시간에 떨어진 나뭇잎들을 채집해서 관찰 일기를 썼어.'),
    (3, '출근', '사회와 소통', 1, '일을 하기 위해 일터로 나가는 것을 말해요.', '아빠는 매일 아침 일찍 회사로 출근하셔.'),
    (3, '취직', '사회와 소통', 2, '직업을 얻어 직장에 다니게 되는 것을 말해요.', '언니가 원하는 회사에 취직했다는 소식을 듣고 정말 기뻤어.'),
    (3, '표현', '감정과 태도', 1, '생각이나 느낌을 말, 글, 그림 등으로 나타내는 거예요.', '사랑하는 마음을 편지로 표현해서 부모님께 드렸어.'),
    (3, '해양', '자연과 환경', 2, '아주 넓고 깊은 바다를 말해요.', '해양 생태계를 지키기 위해 바다에 쓰레기를 버리면 안 돼.'),
    (3, '가상', '과학과 기술', 2, '실제로 있지는 않지만, 마치 있는 것처럼 상상해서 만든 것을 말해요.', '컴퓨터 게임 속 가상 세계에서 친구들과 만나 신나게 놀았어.'),
    (3, '개선', '생각과 공부', 2, '잘못된 점이나 부족한 점을 고쳐서 더 좋게 만드는 것을 말해요.', '급식 줄 서기 방법을 개선했더니 점심시간이 훨씬 여유로워졌어.'),
    (3, '건축물', '우리 역사', 1, '집, 다리, 탑처럼 사람의 손으로 정성껏 지은 모든 건물을 말해요.', '경복궁은 우리나라를 대표하는 아주 아름다운 전통 건축물이야.'),
    (3, '고유', '우리 역사', 3, '다른 것에는 없고 그 대상만이 특별히 가지고 있는 것을 말해요.', '한글은 전 세계에서 인정받는 우리 민족 고유의 문자야.'),
    (3, '공공 기관', '사회와 소통', 2, '우리 모두의 이익과 편리한 생활을 위해 국가에서 운영하는 곳이에요.', '시청이나 우체국, 경찰서는 우리 생활을 도와주는 소중한 공공 기관이야.'),
    (3, '과거', '우리 역사', 1, '이미 지나간 시간을 말해요. 어제나 작년, 옛날 옛적 등이 포함돼요.', '박물관에 가면 우리 조상님들이 과거에 어떻게 사셨는지 알 수 있어.'),
    (3, '과밀', '사회와 소통', 3, '좁은 곳에 사람이 너무 많이 모여서 아주 복잡한 상태를 말해요.', '도시로 사람들이 너무 많이 모여서 교실이 부족해지는 과밀 문제가 생기기도 해.'),
    (3, '교육', '학교생활', 1, '지식을 배우고 훌륭한 사람으로 자랄 수 있도록 가르치고 배우는 일이에요.', '우리는 학교에서 다양한 교육을 받으며 꿈을 키워 나가고 있어.'),
    (3, '권리', '사회와 소통', 2, '법이나 규칙에 따라 당당하게 요구하거나 누릴 수 있는 힘을 말해요.', '어린이는 누구나 즐겁게 놀고 공부할 수 있는 권리가 있어.'),
    (3, '기능', '과학과 기술', 2, '어떤 물건이나 사람의 몸이 맡아서 하는 특별한 역할을 말해요.', '스마트폰에는 사진을 찍거나 길을 찾는 등 정말 다양한 기능이 들어 있어.'),
    (3, '기준', '생각과 공부', 2, '어떤 것을 비교하거나 분류할 때 중심이 되는 규칙이나 잣대를 말해요.', '키를 기준으로 키가 작은 친구부터 큰 친구 순서대로 줄을 섰어.'),
    (3, '나열', '말과 글', 2, '물건이나 단어를 하나하나 늘어놓는 것을 말해요.', '좋아하는 과일 이름을 공책에 쭉 나열해서 적어 보았어.'),
    (3, '다양', '사회와 소통', 1, '모양이나 성질 등이 서로 다르고 여러 가지인 것을 말해요.', '우리 반 친구들은 좋아하는 운동이 아주 다양해.'),
